<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$id=$_GET['id']??$_POST['id']??'';$s=$pdo->prepare("SELECT a.id,a.public_id,s.canonical_url FROM annotations a JOIN sources s ON s.id=a.source_id WHERE a.public_id=? AND a.visibility='public'");$s->execute([$id]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Annotation not found.');}$done=false;$error='';if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$email=trim($_POST['email']??'');$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$type=$_POST['claim_type']??'other';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$name===''||$desc==='')$error='Complete all required fields.';else{$q=$pdo->prepare('INSERT INTO rights_claims(public_id,annotation_id,claimant_name,claimant_email,claim_type,description) VALUES(?,?,?,?,?,?)');$q->execute([ulid_like(),$a['id'],$name,$email,$type,$desc]);$done=true;}}
?><!doctype html><html><head><meta charset="utf-8"><title>File a claim · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="panel narrow"><h1>File a claim</h1><p>This form is available without an Annotated account.</p><?php if($done):?><div class="success">Your claim has been submitted for review.</div><?php else:?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($id)?>"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Claim type<select name="claim_type"><option value="copyright">Copyright / fair-use concern</option><option value="ownership">Ownership</option><option value="incorrect_attribution">Incorrect attribution</option><option value="privacy">Privacy</option><option value="other">Other legal concern</option></select></label><label>Description<textarea name="description" rows="7" required></textarea></label><button>Submit claim</button></form><?php endif?></main></body></html>
